parameters.functionCode:
const trafficResponse = $node['Fetch GA4 Traffic Data'].json;
const pagesResponse = $node['Fetch GA4 Top Pages'].json;

// Parse traffic data
const trafficRows = trafficResponse.rows || [];
const trafficByChannel = {};
let totalMetrics = {
  sessions: 0,
  users: 0,
  new_users: 0,
  bounce_rate: 0,
  avg_session_duration: 0,
  pageviews: 0,
  conversions: 0
};

for (const row of trafficRows) {
  const channel = row.dimensionValues?.[1]?.value || 'Unknown';
  const metrics = row.metricValues || [];

  const channelData = {
    sessions: parseInt(metrics[0]?.value || 0),
    users: parseInt(metrics[1]?.value || 0),
    new_users: parseInt(metrics[2]?.value || 0),
    bounce_rate: parseFloat(metrics[3]?.value || 0),
    avg_duration: parseFloat(metrics[4]?.value || 0),
    pageviews: parseInt(metrics[5]?.value || 0),
    conversions: parseInt(metrics[6]?.value || 0)
  };

  trafficByChannel[channel] = channelData;
  totalMetrics.sessions += channelData.sessions;
  totalMetrics.users += channelData.users;
  totalMetrics.new_users += channelData.new_users;
  totalMetrics.pageviews += channelData.pageviews;
  totalMetrics.conversions += channelData.conversions;
}

// Parse top pages
const pageRows = pagesResponse.rows || [];
const topPages = pageRows.slice(0, 10).map(row => ({
  path: row.dimensionValues?.[0]?.value || '/',
  pageviews: parseInt(row.metricValues?.[0]?.value || 0),
  avg_duration: parseFloat(row.metricValues?.[1]?.value || 0),
  bounce_rate: parseFloat(row.metricValues?.[2]?.value || 0)
}));

const date = trafficRows[0]?.dimensionValues?.[0]?.value || new Date(Date.now() - 86400000).toISOString().split('T')[0];

return [{
  json: {
    date: date,
    total: totalMetrics,
    by_channel: trafficByChannel,
    top_pages: topPages
  }
}];

